// Turn active client_config rows into a lookup keyed by client_code, carrying the
// column map, status map, valid currencies and date formats each client needs for parsing.
const run = $('Set Run Context').first().json;
const rows = $input.all().map(i => i.json).map(j => j.fields || j).filter(f => f && f.client_code);

const clients = [];
const problems = [];
for (const f of rows) {
  const code = String(f.client_code).trim().toUpperCase();
  const parseJson = (raw, label) => {
    try { return JSON.parse(raw || '{}'); }
    catch (e) { problems.push(code + ': ' + label + ' is not valid JSON'); return null; }
  };
  const columnMap = parseJson(f.column_map_json, 'column_map_json');
  const statusMap = parseJson(f.status_map_json, 'status_map_json');
  const validCurrencies = parseJson(f.valid_currencies_json, 'valid_currencies_json');
  if (!columnMap || !statusMap || !validCurrencies) { problems.push(code + ': client skipped, fix config'); continue; }
  clients.push({
    client_code: code,
    client_name: f.client_name || code,
    columnMap,
    statusMap,
    validCurrencies: validCurrencies.map(c => String(c).toUpperCase()),
    dateFormats: String(f.date_formats || '').split(',').map(s => s.trim()).filter(Boolean),
  });
}
return [{ json: { run_id: run.run_id, clients, config_problems: problems } }];

// Normalize, validate, deduplicate and conflict-check one Source A file's rows.
// Emits three kinds of items via _kind: canonical, exception, file_summary.

function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  return h.toString(16);
}
function num(v) {
  if (v === undefined || v === null || v === '') return null;
  const n = parseFloat(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}
function intFromString(v) {
  if (v === undefined || v === null || v === '') return null;
  const m = String(v).match(/-?\d+/);
  return m ? parseInt(m[0], 10) : null;
}
function round2(n) { return n === null ? null : Math.round((n + Number.EPSILON) * 100) / 100; }

function parseDateFlexible(raw, formats) {
  const s = String(raw || '').trim();
  for (const fmt of formats) {
    let m, y, mo, d;
    if (fmt === 'YYYY-MM-DD') { m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/); if (m) { y = m[1]; mo = m[2]; d = m[3]; } }
    else if (fmt === 'DD/MM/YYYY') { m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/); if (m) { d = m[1]; mo = m[2]; y = m[3]; } }
    else if (fmt === 'DD-MM-YYYY') { m = s.match(/^(\d{2})-(\d{2})-(\d{4})$/); if (m) { d = m[1]; mo = m[2]; y = m[3]; } }
    if (!m) continue;
    const iso = `${y}-${mo}-${d}`;
    const check = new Date(iso + 'T00:00:00Z');
    if (check.getUTCFullYear() == y && (check.getUTCMonth() + 1) == parseInt(mo, 10) && check.getUTCDate() == parseInt(d, 10)) {
      return { iso, ok: true };
    }
  }
  return { iso: null, ok: false };
}

const SKU_RE = /\b([A-Za-z]{2,4})-{1,2}(\d{3,5})-([A-Za-z0-9]{1,3})\b/;
function extractSku(text) {
  const m = String(text || '').match(SKU_RE);
  if (!m) return null;
  return `${m[1].toUpperCase()}-${m[2]}-${m[3].toUpperCase()}`;
}

function cleanEmail(raw) {
  const s = String(raw || '').trim().toLowerCase();
  const repaired = s.replace(/@+/g, '@');
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(repaired);
  return { email: repaired, ok, wasMalformed: s !== repaired && s.length > 0, domain: ok ? repaired.split('@')[1] : null };
}

const ctx = $('Build Client Routes').first().json;
const run = $('Set Run Context').first().json;
const fileRun = $('Loop Over Pending Files').first().json;
const client = ctx.clients.find(c => c.client_code === fileRun.client_code);

const exceptions = [];
const summary = { rows_read: 0, rows_written: 0, rows_rejected: 0, rows_duplicate_ignored: 0, rows_conflict: 0, rows_review: 0 };

function pushException(orderRef, lineNo, issueType, description, valueSeen, valueAlternative, actionTaken, severity) {
  exceptions.push({ json: { _kind: 'exception',
    exception_id: `${fileRun.client_code}|${orderRef}|${lineNo}|${issueType}`,
    run_id: run.run_id, client_code: fileRun.client_code, source_type: 'source_a', source_file_id: fileRun.file_id,
    order_ref: orderRef, line_no: String(lineNo), issue_type: issueType, description,
    value_seen: valueSeen == null ? '' : String(valueSeen),
    value_alternative: valueAlternative == null ? '' : String(valueAlternative),
    action_taken: actionTaken, severity, created_at: new Date().toISOString(), resolved: false,
  }});
}

if (!client) {
  return [{ json: { _kind: 'file_summary', ...summary, run_id: run.run_id, file_run_id: fileRun.id,
    client_code: fileRun.client_code, note: 'client_code not found in active client_config, file skipped' } }];
}
const cm = client.columnMap;
const get = (row, key) => row[cm[key]];

// ---- pass 1: read + normalize + validate each raw row ----
const normalized = [];
for (const item of $('Extract from File').all()) {

  const row = item.json;
  const orderRefRaw = get(row, 'order_ref');
  if (orderRefRaw === undefined || orderRefRaw === null || String(orderRefRaw).trim() === '') continue; // blank trailing row
  summary.rows_read++;

  const orderRef = String(orderRefRaw).trim().toUpperCase();
  const lineNo = intFromString(get(row, 'line_no')) ?? 1;
  const issues = [];
  let intakeStatus = 'clean';
  const flag = (status) => { if (status === 'rejected') intakeStatus = 'rejected'; else if (intakeStatus === 'clean') intakeStatus = status; };

  const dateRaw = get(row, 'order_date');
  const dateParsed = parseDateFlexible(dateRaw, client.dateFormats);
  if (!dateParsed.ok) { issues.push(['unparseable_date', dateRaw, null, `Could not parse date with formats ${client.dateFormats.join('/')}`]); flag('rejected'); }

  const emailInfo = cleanEmail(get(row, 'customer_email'));
  if (emailInfo.wasMalformed) issues.push(['malformed_email', get(row, 'customer_email'), emailInfo.email, 'Collapsed repeated @ to parse a usable email']);

  const nameRaw = String(get(row, 'customer_name') || '').replace(/\s+/g, ' ').trim();

  const qty = intFromString(get(row, 'quantity'));
  const qtyRaw = get(row, 'quantity');
  if (qty === null) { issues.push(['missing_quantity', qtyRaw, null, 'Quantity missing or unparseable']); flag('rejected'); }
  else if (qty < 0) { issues.push(['negative_quantity', qty, null, 'Negative quantity is not a valid order line']); flag('rejected'); }
  else if (String(qtyRaw) !== String(qty)) { issues.push(['quantity_text_suffix', qtyRaw, qty, 'Parsed numeric quantity from text']); }

  const unitPrice = num(get(row, 'unit_price'));
  if (unitPrice === null) { issues.push(['missing_unit_price', get(row, 'unit_price'), null, 'Unit price missing or unparseable']); flag('rejected'); }

  const costPrice = num(get(row, 'cost_price'));
  if (costPrice === null) { issues.push(['missing_cost_price', get(row, 'cost_price'), null, 'Cost price missing; margin cannot be computed until supplied']); flag('review'); }

  const currency = String(get(row, 'currency') || '').trim().toUpperCase();
  if (!client.validCurrencies.includes(currency)) { issues.push(['invalid_currency', currency, client.validCurrencies.join('/'), 'Currency code is not in the accepted list for this client']); flag('rejected'); }

  const vatRate = num(get(row, 'vat_rate'));

  const productString = get(row, 'product_string');
  const sku = extractSku(productString);
  if (!sku) { issues.push(['sku_not_found', productString, null, 'No SKU pattern found in item description']); flag('review'); }

  const statusRaw = String(get(row, 'status') || '').trim().toLowerCase();
  const orderStatus = client.statusMap[statusRaw] || null;
  if (!orderStatus) { issues.push(['unknown_order_status', statusRaw, Object.keys(client.statusMap).join('/'), 'Status value not recognised for this client']); flag('review'); }

  const stated = num(get(row, 'stated_line_total'));
  const computed = (qty !== null && unitPrice !== null) ? round2(qty * unitPrice) : null;
  let mismatch = false;
  if (stated !== null && computed !== null && Math.abs(stated - computed) > 0.005) {
    mismatch = true;
    issues.push(['line_total_mismatch', stated, computed, 'Stated line total does not equal quantity times unit price; computed value used']);
  }

  const splitPct = num(get(row, 'split_pct'));

  const compareFields = {
    order_date_iso: dateParsed.iso, customer_name_clean: null, customer_email_clean: emailInfo.ok ? emailInfo.email : null,
    sales_rep: get(row, 'sales_rep') || null, split_rep: get(row, 'split_rep') || null, split_pct: splitPct,
    sku, quantity: qty, unit_price: unitPrice, cost_price: costPrice, currency, vat_rate: vatRate, order_status: orderStatus,
  };
  const hashInput = JSON.stringify(compareFields);

  normalized.push({
    orderRef, lineNo, nameRaw, emailDomain: emailInfo.domain, emailClean: emailInfo.ok ? emailInfo.email : null,
    productString, dedupeKey: `${fileRun.client_code}|${orderRef}|${lineNo}`, hash: djb2(hashInput),
    compareFields, stated, computed, mismatch, intakeStatus, issues,
  });
}

// ---- customer name resolution: group by email domain (fallback: normalized name) ----
const nameGroups = new Map();
for (const r of normalized) {
  const key = r.emailDomain || r.nameRaw.toLowerCase().replace(/[.,]/g, '').trim();
  if (!nameGroups.has(key)) nameGroups.set(key, []);
  nameGroups.get(key).push(r);
}
for (const [, members] of nameGroups) {
  const counts = new Map();
  for (const m of members) counts.set(m.nameRaw, (counts.get(m.nameRaw) || 0) + 1);
  const isMixedCase = (s) => /[a-z]/.test(s) && /[A-Z]/.test(s);
  let best = null, bestScore = -1;
  for (const [name, count] of counts) {
    const score = (isMixedCase(name) ? 1000 : 0) + count;
    if (score > bestScore) { bestScore = score; best = name; }
  }
  for (const m of members) {
    m.compareFields.customer_name_clean = best;
    if (m.nameRaw !== best) {
      pushException(m.orderRef, m.lineNo, 'customer_name_variant', `Customer name "${m.nameRaw}" normalized to "${best}"`, m.nameRaw, best, 'Used the majority mixed-case spelling for this customer group', 'low');
    }
  }
}

// ---- pass 2: group by dedupe key (existing record + this file's rows), resolve duplicates and conflicts ----
const existingByKey = new Map();
for (const item of $('Search Existing Canonical For Client').all()) {
  const f = item.json.fields || item.json;
  if (f.canonical_line_id) existingByKey.set(f.canonical_line_id, { airtableId: item.json.id, fields: f });
}

const byKey = new Map();
for (const r of normalized) { if (!byKey.has(r.dedupeKey)) byKey.set(r.dedupeKey, []); byKey.get(r.dedupeKey).push(r); }

const canonicalOut = [];
const CANON_FIELDS = ['order_date_iso', 'customer_name_clean', 'customer_email_clean', 'sales_rep', 'split_rep', 'split_pct', 'sku', 'quantity', 'unit_price', 'cost_price', 'currency', 'vat_rate', 'order_status'];

for (const [key, rows] of byKey) {
  for (const r of rows) for (const [type, seen, alt, desc] of r.issues) {
    pushException(r.orderRef, r.lineNo, type, desc, seen, alt, type === 'line_total_mismatch' ? 'Computed value used for downstream calculations' : (type.endsWith('quantity') || type === 'invalid_currency' || type === 'missing_unit_price') ? 'Row excluded from totals pending correction' : 'Flagged for review, row still processed', 'negative_quantity,invalid_currency,missing_quantity,missing_unit_price,unparseable_date'.includes(type) ? 'high' : 'medium');
  }

  const existing = existingByKey.get(key);
  const distinctHashes = new Set(rows.map(r => r.hash));
  const allHashes = existing ? new Set([existing.fields.payload_hash, ...distinctHashes]) : distinctHashes;

  if (allHashes.size === 1 && existing && distinctHashes.has(existing.fields.payload_hash)) {
    summary.rows_duplicate_ignored += rows.length;
    pushException(rows[0].orderRef, rows[0].lineNo, 'duplicate_ignored', `File resent ${rows.length} row(s) identical to the record already on file`, fileRun.file_name, existing.fields.last_seen_file_id, 'No write performed; existing record already correct', 'low');
    continue;
  }

  if (allHashes.size === 1) {
    if (rows.length > 1) {
      summary.rows_duplicate_ignored += rows.length - 1;
      pushException(rows[0].orderRef, rows[0].lineNo, 'duplicate_within_file', `${rows.length} identical rows for this line in one file; one record kept`, rows.length, 1, 'Extra identical copies ignored', 'low');
    }
    const r = rows[0];
    const finalStatus = r.intakeStatus;
    if (finalStatus === 'rejected') summary.rows_rejected++; else if (finalStatus === 'review') summary.rows_review++;
    summary.rows_written++;
    canonicalOut.push({ json: { _kind: 'canonical',
      canonical_line_id: key, run_id: run.run_id, client_code: fileRun.client_code, source_type: 'source_a',
      order_ref: r.orderRef, line_no: r.lineNo, order_date_raw: '', order_date_iso: r.compareFields.order_date_iso,
      customer_name_raw: r.nameRaw, customer_name_clean: r.compareFields.customer_name_clean,
      customer_email_raw: r.emailClean, customer_email_clean: r.compareFields.customer_email_clean,
      sales_rep: r.compareFields.sales_rep, split_rep: r.compareFields.split_rep, split_pct: r.compareFields.split_pct,
      product_string_raw: r.productString, sku: r.compareFields.sku, quantity: r.compareFields.quantity,
      unit_price: r.compareFields.unit_price, cost_price: r.compareFields.cost_price,
      stated_line_total: r.stated, computed_line_total: r.computed, line_total_mismatch: r.mismatch,
      currency: r.compareFields.currency, vat_rate: r.compareFields.vat_rate, order_status: r.compareFields.order_status,
      intake_status: finalStatus, conflict_flag: false, conflict_fields: '', conflict_values_json: '',
      sources_seen: 'A', payload_hash: r.hash, last_seen_file_id: fileRun.file_id, last_seen_run_id: run.run_id,
      updated_at: new Date().toISOString(),
    }});
    continue;
  }

  // conflict: per-field resolution across existing + all distinct new versions
  const versions = [];
  if (existing) versions.push({ source: existing.fields.last_seen_file_id || 'existing', fields: existing.fields });
  const seenHashes = new Set();
  for (const r of rows) { if (!seenHashes.has(r.hash)) { seenHashes.add(r.hash); versions.push({ source: fileRun.file_name, fields: r.compareFields }); } }

  const resolved = {}; const conflictingFields = [];
  for (const f of CANON_FIELDS) {
    const vals = [...new Set(versions.map(v => JSON.stringify(v.fields[f] ?? null)))];
    if (vals.length === 1) resolved[f] = JSON.parse(vals[0]);
    else { resolved[f] = null; conflictingFields.push(f); }
  }
  const last = rows[rows.length - 1];
  summary.rows_conflict++;
  pushException(last.orderRef, last.lineNo, 'conflicting_duplicate', `${versions.length} differing versions of this line found across ${versions.map(v => v.source).join(' and ')}; fields in conflict: ${conflictingFields.join(', ')}`, JSON.stringify(versions[0].fields), JSON.stringify(versions[versions.length - 1].fields), 'Held out of totals pending manual resolution; all versions preserved in conflict_values_json', 'high');
  summary.rows_written++;
  canonicalOut.push({ json: { _kind: 'canonical',
    canonical_line_id: key, run_id: run.run_id, client_code: fileRun.client_code, source_type: 'source_a',
    order_ref: last.orderRef, line_no: last.lineNo, order_date_raw: '', order_date_iso: resolved.order_date_iso,
    customer_name_raw: last.nameRaw, customer_name_clean: resolved.customer_name_clean,
    customer_email_raw: last.emailClean, customer_email_clean: resolved.customer_email_clean,
    sales_rep: resolved.sales_rep, split_rep: resolved.split_rep, split_pct: resolved.split_pct,
    product_string_raw: last.productString, sku: resolved.sku, quantity: resolved.quantity,
    unit_price: resolved.unit_price, cost_price: resolved.cost_price,
    stated_line_total: null, computed_line_total: (resolved.quantity != null && resolved.unit_price != null) ? Math.round(resolved.quantity * resolved.unit_price * 100) / 100 : null,
    line_total_mismatch: false, currency: resolved.currency, vat_rate: resolved.vat_rate, order_status: resolved.order_status,
    intake_status: 'conflict', conflict_flag: true, conflict_fields: conflictingFields.join(','),
    conflict_values_json: JSON.stringify(versions),
    sources_seen: 'A', payload_hash: 'CONFLICT', last_seen_file_id: fileRun.file_id, last_seen_run_id: run.run_id,
    updated_at: new Date().toISOString(),
  }});
}

const out = [...canonicalOut, ...exceptions];
out.push({ json: { _kind: 'file_summary', ...summary, run_id: run.run_id, file_run_id: fileRun.id, client_code: fileRun.client_code, note: '' } });
return out;

// Aggregate this run's Source A parse results into one run_summary row.
const run = $('Set Run Context').first().json;
const rows = $input.all().map(i => i.json.fields || i.json).filter(f => f.run_id === run.run_id);
const sum = (k) => rows.reduce((a, r) => a + (Number(r[k]) || 0), 0);
const filesTouched = rows.length;
const clients = [...new Set(rows.map(r => r.client_code))];
return [{ json: {
  run_id: run.run_id, stage: 'parse_source_a', execution_mode: run.execution_mode, started_at: run.started_at,
  finished_at: new Date().toISOString(), status: filesTouched ? 'parse_complete' : 'parse_complete_no_files',
  active_clients: clients.length, files_listed: filesTouched, files_new: 0, files_already_received: 0, files_unrecognised: 0,
  rows_read: sum('rows_read'), rows_written: sum('rows_written'), rows_rejected: sum('rows_rejected'),
  rows_duplicate_ignored: sum('rows_duplicate_ignored'), conflicts: sum('rows_conflict'),
  notes: filesTouched ? `Parsed ${filesTouched} file(s) for ${clients.join(', ')}` : 'No pending Source A file_runs found (status=received)',
} }];
